-- V1 Baseline Schema

-- TABLES
create table academic_year (end_date date, is_active boolean, start_date date, created_at timestamp(6) with time zone, id bigint generated by default as identity, updated_at timestamp(6) with time zone, name varchar(255), primary key (id));

create table add_drop_request (course_offering_id bigint not null, created_at timestamp(6) with time zone, id bigint generated by default as identity, processed_by bigint, student_id bigint not null, reason varchar(255), request_type varchar(255) not null, status varchar(255) not null, primary key (id));

create table admission_application (merit_score float(53), academic_year_id bigint not null, applicant_id bigint not null, created_at timestamp(6) with time zone, id bigint generated by default as identity, program_id bigint not null, submitted_at timestamp(6) with time zone, updated_at timestamp(6) with time zone, application_number varchar(255) not null unique, reviewer_remarks TEXT, status varchar(255) not null check (status in ('DRAFT','SUBMITTED','UNDER_REVIEW','DOCUMENT_VERIFICATION_PENDING','WAITLISTED','ADMITTED','REJECTED','ENROLLED')), primary key (id));

create table admission_inquiry (created_at timestamp(6) with time zone, id bigint generated by default as identity, email varchar(255) not null, notes varchar(255), phone varchar(255) not null, program_of_interest varchar(255), prospect_name varchar(255) not null, status varchar(255) not null, primary key (id));

create table applicant (date_of_birth date not null, created_at timestamp(6) with time zone, id bigint generated by default as identity, updated_at timestamp(6) with time zone, address TEXT, email varchar(255) not null unique, first_name varchar(255) not null, gender varchar(255), last_name varchar(255) not null, phone varchar(255) not null unique, primary key (id));

create table applicant_document (applicant_id bigint not null, id bigint generated by default as identity, uploaded_at timestamp(6) with time zone, verified_at timestamp(6) with time zone, document_type varchar(255) not null, file_url varchar(255) not null, remarks TEXT, verification_status varchar(255) not null, primary key (id));

create table attendance_alert (course_offering_id bigint not null, created_at timestamp(6) with time zone, id bigint generated by default as identity, student_id bigint not null, alert_type varchar(255) not null, message varchar(255), status varchar(255) not null, primary key (id));

create table attendance_correction (approved_by bigint, attendance_record_id bigint not null, id bigint generated by default as identity, requested_at timestamp(6) with time zone, requested_by bigint not null, new_status varchar(255) not null, old_status varchar(255) not null, reason varchar(255) not null, status varchar(255) not null, primary key (id));

create table batch (admission_year integer, graduation_year integer, is_active boolean, academic_year_id bigint, created_at timestamp(6) with time zone, id bigint generated by default as identity, program_id bigint, updated_at timestamp(6) with time zone, code varchar(255), name varchar(255), primary key (id));

create table campus (created_at timestamp(6) with time zone, id bigint generated by default as identity, institution_id bigint, updated_at timestamp(6) with time zone, address varchar(255), name varchar(255), primary key (id));

create table class_schedule (faculty_id bigint not null, id bigint generated by default as identity, room_id bigint not null, section_id bigint not null, time_slot_id bigint not null, primary key (id), unique (room_id, time_slot_id), unique (faculty_id, time_slot_id), unique (section_id, time_slot_id));

create table course (credits integer, is_active boolean, created_at timestamp(6) with time zone, department_id bigint, id bigint generated by default as identity, program_id bigint, updated_at timestamp(6) with time zone, code varchar(255), course_type varchar(255), name varchar(255), primary key (id));

create table course_offering (is_published boolean not null, max_capacity integer not null, course_id bigint not null, id bigint generated by default as identity, semester_id bigint not null, primary key (id), unique (course_id, semester_id));

create table course_prerequisite (course_id bigint not null, id bigint generated by default as identity, prerequisite_course_id bigint not null, primary key (id), unique (course_id, prerequisite_course_id));

create table course_registration (course_offering_id bigint not null, dropped_at timestamp(6) with time zone, id bigint generated by default as identity, registered_at timestamp(6) with time zone, section_id bigint not null, student_id bigint not null, status varchar(255) not null check (status in ('DRAFT','REGISTERED','WAITLISTED','DROPPED')), primary key (id), unique (student_id, course_offering_id));

create table credit_rule (max_credits_limit integer not null, min_credits_required integer not null, id bigint generated by default as identity, semester_id bigint not null, primary key (id));

create table curriculum (is_active boolean, total_credits integer, created_at timestamp(6) with time zone, effective_academic_year_id bigint, id bigint generated by default as identity, program_id bigint, semester_id bigint, updated_at timestamp(6) with time zone, version varchar(255), primary key (id));

create table curriculum_course (credits integer not null, course_id bigint not null, created_at timestamp(6) with time zone, curriculum_id bigint not null, id bigint generated by default as identity, classification varchar(255) not null, course_code varchar(255), course_name varchar(255), primary key (id));

create table department (campus_id bigint, created_at timestamp(6) with time zone, id bigint generated by default as identity, updated_at timestamp(6) with time zone, code varchar(255), name varchar(255), primary key (id));

create table fee_head (active boolean, created_at timestamp(6) with time zone, id bigint generated by default as identity, code varchar(255) not null unique, description varchar(255), name varchar(255) not null, primary key (id));

create table fee_structure (active boolean, academic_year_id bigint, created_at timestamp(6) with time zone, id bigint generated by default as identity, program_id bigint, code varchar(255) not null unique, name varchar(255) not null, primary key (id));

create table fee_structure_component (amount numeric(12,2) not null, fee_head_id bigint not null, fee_structure_id bigint not null, id bigint generated by default as identity, primary key (id), unique (fee_structure_id, fee_head_id));

create table finance_concession (value numeric(12,2) not null, approved_at timestamp(6) with time zone, created_at timestamp(6) with time zone, fee_head_id bigint not null, id bigint generated by default as identity, student_id bigint not null, approved_by varchar(255), reason varchar(255), status varchar(255) not null check (status in ('PENDING','APPROVED','REJECTED','REVOKED')), type varchar(255) not null, primary key (id));

create table finance_payment (amount numeric(12,2) not null, payment_date date not null, created_at timestamp(6) with time zone, id bigint generated by default as identity, student_fee_id bigint not null, student_id bigint not null, created_by varchar(255), payment_method varchar(255) not null check (payment_method in ('CASH','BANK_TRANSFER','CARD','UPI','ONLINE','OTHER')), reference_number varchar(255) not null unique, remarks varchar(255), status varchar(255) not null check (status in ('PENDING','SUCCESS','FAILED','CANCELLED','REVERSED')), primary key (id));

create table finance_payment_allocation (allocated_amount numeric(12,2) not null, id bigint generated by default as identity, payment_id bigint not null, student_fee_component_id bigint not null, primary key (id));

create table finance_receipt (generated_at timestamp(6) with time zone not null, id bigint generated by default as identity, payment_id bigint not null unique, student_id bigint not null, receipt_number varchar(255) not null unique, status varchar(255) not null check (status in ('PENDING','SUCCESS','FAILED','CANCELLED','REVERSED')), primary key (id));

create table finance_scholarship (active boolean, value numeric(12,2) not null, created_at timestamp(6) with time zone, id bigint generated by default as identity, eligibility varchar(255), name varchar(255) not null, type varchar(255) not null, primary key (id));

create table finance_student_scholarship (amount numeric(12,2) not null, academic_year_id bigint not null, approved_at timestamp(6) with time zone, id bigint generated by default as identity, scholarship_id bigint not null, student_id bigint not null, approved_by varchar(255), status varchar(255) not null check (status in ('PENDING','APPROVED','REJECTED','REVOKED')), primary key (id));

create table guardians (is_emergency_contact boolean not null, created_at timestamp(6), id bigint generated by default as identity, student_id bigint, updated_at timestamp(6), phone varchar(20) not null, relation varchar(50) not null, first_name varchar(100) not null, last_name varchar(100) not null, occupation varchar(100), email varchar(150), address varchar(255), primary key (id));

create table institution (created_at timestamp(6) with time zone, id bigint generated by default as identity, updated_at timestamp(6) with time zone, code varchar(255), name varchar(255), primary key (id));

create table leave_request (end_date date not null, start_date date not null, created_at timestamp(6) with time zone, id bigint generated by default as identity, student_id bigint not null, reason varchar(255), status varchar(255) not null, primary key (id));

create table program (duration integer, is_active boolean, created_at timestamp(6) with time zone, department_id bigint, id bigint generated by default as identity, updated_at timestamp(6) with time zone, code varchar(255), degree varchar(255), name varchar(255), primary key (id));

create table room (capacity integer not null, is_active boolean, id bigint generated by default as identity, name varchar(255) not null unique, primary key (id));

create table section (capacity integer not null, current_enrollment integer, is_active boolean, course_offering_id bigint not null, created_at timestamp(6) with time zone, id bigint generated by default as identity, updated_at timestamp(6) with time zone, name varchar(255) not null, primary key (id));

create table section_faculty (assigned_at timestamp(6) with time zone, faculty_id bigint not null, id bigint generated by default as identity, section_id bigint not null, subject_id bigint, role varchar(255) not null, primary key (id));

create table section_student (is_active boolean, assigned_at timestamp(6) with time zone, id bigint generated by default as identity, section_id bigint not null, student_id bigint not null, primary key (id));

create table semester (end_date date, is_active boolean, semester_number integer, start_date date, academic_year_id bigint, created_at timestamp(6) with time zone, id bigint generated by default as identity, updated_at timestamp(6) with time zone, name varchar(255), primary key (id));

create table student_academic_records (cgpa float(53) not null, gpa float(53) not null, academic_year_id bigint not null, created_at timestamp(6), id bigint generated by default as identity, semester_id bigint not null, student_id bigint not null, academic_status varchar(50), primary key (id));

create table student_attendance_record (attendance_date date not null, is_active boolean not null, created_at timestamp(6) with time zone not null, marked_by_faculty_id bigint, record_id bigint generated by default as identity, schedule_id bigint not null, student_id bigint not null, updated_at timestamp(6) with time zone not null, status varchar(20) not null, remarks TEXT, primary key (record_id), constraint uq_student_schedule_attendance unique (student_id, schedule_id, attendance_date));

create table student_categories (created_at timestamp(6), id bigint generated by default as identity, name varchar(50) not null unique, description varchar(255), primary key (id));

create table student_documents (file_size bigint not null, id bigint generated by default as identity, student_id bigint not null, uploaded_at timestamp(6), document_type varchar(50) not null check (document_type in ('AADHAAR','TRANSFER_CERTIFICATE','MIGRATION','MARKSHEET','PHOTOGRAPH')), file_type varchar(100) not null, storage_path varchar(500) not null, file_name varchar(255) not null, original_file_name varchar(255) not null, primary key (id));

create table student_enrollments (enrollment_date date not null, academic_year_id bigint not null, batch_id bigint not null, created_at timestamp(6), id bigint generated by default as identity, program_id bigint not null, semester_id bigint not null, student_id bigint not null, status varchar(30) not null check (status in ('ACTIVE','INACTIVE','SUSPENDED','GRADUATED','ALUMNI','DROPPED','TRANSFERRED')), enrollment_number varchar(50) not null unique, primary key (id), unique (student_id, academic_year_id, semester_id));

create table student_fee (concession_amount numeric(12,2) not null, gross_amount numeric(12,2) not null, net_payable numeric(12,2) not null, outstanding_amount numeric(12,2) not null, paid_amount numeric(12,2) not null, scholarship_amount numeric(12,2) not null, academic_year_id bigint not null, created_at timestamp(6) with time zone, fee_structure_id bigint not null, id bigint generated by default as identity, student_id bigint not null, updated_at timestamp(6) with time zone, status varchar(255) not null check (status in ('PENDING','PARTIALLY_PAID','PAID','OVERDUE','WAIVED','CANCELLED')), primary key (id), unique (student_id, academic_year_id, fee_structure_id));

create table student_fee_component (gross_amount numeric(12,2) not null, outstanding_amount numeric(12,2) not null, paid_amount numeric(12,2) not null, fee_head_id bigint not null, id bigint generated by default as identity, student_fee_id bigint not null, primary key (id));

create table student_history (id bigint generated by default as identity, recorded_at timestamp(6) with time zone, recorded_by bigint, student_id bigint not null, event_type varchar(255) not null, new_state varchar(255), old_state varchar(255), reason varchar(255), primary key (id));

create table student_status_history (effective_date date not null, changed_at timestamp(6), id bigint generated by default as identity, student_id bigint not null, new_status varchar(30) not null check (new_status in ('ACTIVE','INACTIVE','SUSPENDED','GRADUATED','ALUMNI','DROPPED','TRANSFERRED')), previous_status varchar(30) check (previous_status in ('ACTIVE','INACTIVE','SUSPENDED','GRADUATED','ALUMNI','DROPPED','TRANSFERRED')), changed_by varchar(100), reason varchar(500), primary key (id));

create table students (date_of_birth date not null, enrollment_date date not null, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), blood_group varchar(10), gender varchar(20) not null, phone varchar(20) not null, pincode varchar(20), status varchar(30) not null check (status in ('ACTIVE','INACTIVE','SUSPENDED','GRADUATED','ALUMNI','DROPPED','TRANSFERRED')), batch varchar(50) not null, roll_number varchar(50) not null unique, city varchar(100), department varchar(100) not null, first_name varchar(100) not null, last_name varchar(100) not null, program varchar(100), state varchar(100), email varchar(150) not null unique, address varchar(255), primary key (id));

create table subject (credits integer, is_active boolean, is_practical boolean, course_id bigint, created_at timestamp(6) with time zone, department_id bigint, id bigint generated by default as identity, program_id bigint, updated_at timestamp(6) with time zone, code varchar(255) not null unique, name varchar(255) not null, subject_type varchar(255), primary key (id));

create table time_slot (end_time time(6) not null, start_time time(6) not null, id bigint generated by default as identity, day_of_week varchar(255) not null check (day_of_week in ('MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY','SUNDAY')), primary key (id), unique (day_of_week, start_time, end_time));

create table timetable_slot (end_time time(6) not null, is_active boolean, start_time time(6) not null, faculty_id bigint not null, id bigint generated by default as identity, room_id bigint not null, section_id bigint not null, day_of_week varchar(255) not null check (day_of_week in ('MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY','SUNDAY')), primary key (id));

create table faculty (
    faculty_id bigint generated by default as identity primary key,
    first_name varchar(100) not null,
    last_name varchar(100) not null,
    official_email varchar(150) not null unique,
    department_id bigint,
    is_active boolean default true,
    created_at timestamp(6) with time zone default current_timestamp,
    updated_at timestamp(6) with time zone default current_timestamp
);

